type Validator interface{ Validate(v any) error }

type Responder struct {
	validator Validator             // injected hook
	write     func(v any) error
}

func (r *Responder) Respond(v any) error {   // no subclassing in Go
	if err := r.validator.Validate(v); err != nil {
		return err
	}
	return r.write(v)
}
